val detailState = _detailState.asStateFlow()
private val _desktopMetadataAdmission = MutableStateFlow<com.bilipai.desktop.ui.DesktopOriginalVideoMetadataAdmission?>(null)
val desktopMetadataAdmission = _desktopMetadataAdmission.asStateFlow()
private val _desktopMetadataRelatedFailure = MutableStateFlow<Throwable?>(null)
val desktopMetadataRelatedFailure = _desktopMetadataRelatedFailure.asStateFlow()
private var desktopMetadataRelatedJob: Job? = null
private var desktopMetadataRelatedToken: Long = Long.MIN_VALUE
private var desktopMetadataRelatedBvid: String = ""
private val desktopMetadataRelatedScheduler = RelatedVideoLoadScheduler()
private var desktopMetadataRelatedMirroredToken: Long = Long.MIN_VALUE

private fun retireDesktopMetadataRelated(publishReset: Boolean = true) {
    // Cancel transports outside the Store/entry admission monitors.
    desktopMetadataRelatedJob?.cancel()
    desktopMetadataRelatedJob = null
    desktopMetadataRelatedToken = Long.MIN_VALUE
    desktopMetadataRelatedBvid = ""
    desktopMetadataRelatedMirroredToken = Long.MIN_VALUE
    // A retired Root may cancel work, but cannot publish into its guarded UI.
    if (publishReset) {
        _desktopMetadataAdmission.value = null
        _desktopMetadataRelatedFailure.value = null
    }
}

/** Only an actual native publication with this exact original request/token
 * witness may receive playlist/playback side effects. Metadata alone cannot. */
private fun metadataRelatedNativeSource(
    admission: com.bilipai.desktop.ui.DesktopOriginalVideoMetadataAdmission,
    token: Long,
): com.bilipai.desktop.ui.DesktopOriginalVideoAcceptedPublication? {
    if (!admission.ownsSubject() || currentLoadRequestToken != token) return null
    val state = playbackSessionState
    val request = state.currentRequest ?: return null
    val expected = environment.captureNativePublication() ?: return null
    if (expected.nativeSource.source.authorizationReceipt != admission.receipt) return null
    val bootstrap = expected.bootstrapOrigin
    val sameRequest = (bootstrap != null && bootstrap.request === request && bootstrap.requestToken == token &&
        bootstrap.matchesResolvedRequest(expected.request)) ||
        (expected.pageSubject?.sameOriginalRequestIdentity(state) == true)
    return expected.takeIf { sameRequest }
}

private suspend fun runDesktopMetadataRelated(
    scope: com.bilipai.desktop.ui.DesktopOriginalVideoMetadataReadScope,
    bvid: String, token: Long, operation: Job,
) {
    val admission = scope.presentation
    fun current(): Boolean = admission.ownsSubject() && currentLoadRequestToken == token &&
        desktopMetadataRelatedJob === operation && !operation.isCancelled &&
        _desktopMetadataAdmission.value === admission && desktopMetadataRelatedToken == token
    try {
        repeat(2) { attempt ->
            currentCoroutineContext().ensureActive(); scope.assertCurrent()
            if (!current()) throw CancellationException("Readonly related request retired")
            val result: Result<List<RelatedVideo>> = try {
                val cached = scope.cachedRelated(bvid)
                if (cached != null) cached else {
                    val allowed = desktopMetadataRelatedScheduler.awaitPermit(token, snapshot = {
                        scope.assertCurrent()
                        val expected = metadataRelatedNativeSource(admission, token)
                        val native = expected?.let(environment.readRelatedPlaybackState)
                        // WinRT reports real profile/connectivity. Its current ABI
                        // has no capacity sample: defer unknown, never Android's
                        // networkHandle=null => unconstrained default on Windows.
                        val network = environment.network.relatedNetworkObservation()
                        RelatedVideoLoadSnapshot(
                            requestToken = if (current()) token else Long.MIN_VALUE,
                            constrainedNetwork = network.constrainedOrUnknown,
                            hasCachedRelated = scope.cachedRelated(bvid) != null,
                            playbackPrepared = expected != null && native != null,
                            firstFrameRendered = native?.firstVideoFrameReady == true,
                            playbackReady = native?.ready == true,
                            buffering = native?.pausedForCache == true || native?.loading == true,
                            playWhenReady = native?.let { !(it.nativePaused ?: it.paused) } ?: desktopLoadPlayWhenReady,
                            bufferedDurationMs = native?.bufferedForwardSeconds?.takeIf { it.isFinite() && it >= 0.0 }
                                ?.let { (it * 1000.0).toLong() } ?: 0L,
                            playbackFailed = _uiState.value is VideoPlaybackUiState.Error || native?.error != null,
                            playbackEnded = native?.ended == true,
                        )
                    })
                    if (!allowed || !current()) throw CancellationException("Readonly related scheduler retired")
                    // Preserve the original stable policy: 8s x 2, 500ms
                    // retry; timeout is failure, successful empty is READY.
                    withTimeoutOrNull(8_000L) { scope.related(bvid) }
                        ?: Result.failure(IllegalStateException("相关推荐请求超时"))
                }
            } catch (cancelled: CancellationException) { throw cancelled }
            catch (failure: Exception) { Result.failure(failure) }
            (result.exceptionOrNull() as? CancellationException)?.let { throw it }
            currentCoroutineContext().ensureActive(); scope.assertCurrent()
            if (!current()) throw CancellationException("Readonly related result retired")
            if (result.isFailure && attempt == 0) { delay(500L); return@repeat }
            val related = result.getOrDefault(emptyList())
            val loadState = if (result.isSuccess) VideoPlaybackUiState.RelatedLoadState.READY
                else VideoPlaybackUiState.RelatedLoadState.FAILED
            if (!admission.admit {
                if (!current()) throw CancellationException("Readonly related commit retired")
                _desktopMetadataRelatedFailure.value = result.exceptionOrNull()
                _detailState.update { state ->
                    if (state.requestToken == token) state.copy(related = related, relatedLoadState = loadState)
                    else state
                }
            }) throw CancellationException("Readonly related entry retired")
            // A separate REAL native gate is required for Success/playlist.
            // No synthetic contentSnapshot(empty playUrl) is ever consumed.
            mirrorDesktopMetadataRelatedAfterNative(admission, token)
            return
        }
    } catch (cancelled: CancellationException) { throw cancelled }
    catch (failure: Exception) {
        // A readonly auxiliary failure cannot kill the actual playback
        // parent. Preserve a completed READY result; classify pending reads.
        admission.admit {
            if (current() && _detailState.value.relatedLoadState == VideoPlaybackUiState.RelatedLoadState.LOADING) {
                _desktopMetadataRelatedFailure.value = failure
                _detailState.update { if (it.requestToken == token)
                    it.copy(relatedLoadState = VideoPlaybackUiState.RelatedLoadState.FAILED) else it }
            }
        }
    } finally {
        // Presentation keeps only its entry witness. Do not retain this raw
        // Binding/context to make UI clicks work after the HTTP Job completes.
        admission.admit {
            if (desktopMetadataRelatedJob === operation) desktopMetadataRelatedJob = null
        }
    }
}

private fun mirrorDesktopMetadataRelatedAfterNative(
    admission: com.bilipai.desktop.ui.DesktopOriginalVideoMetadataAdmission, token: Long,
) {
    val detail = _detailState.value
    if (desktopMetadataRelatedMirroredToken == token || detail.requestToken != token ||
        detail.relatedLoadState == VideoPlaybackUiState.RelatedLoadState.LOADING) return
    val expected = metadataRelatedNativeSource(admission, token) ?: return
    var preload = emptyList<RelatedVideo>()
    environment.admitNativePublication(expected) {
        if (metadataRelatedNativeSource(admission, token) === expected &&
            _desktopMetadataAdmission.value === admission && currentLoadRequestToken == token &&
            _detailState.value === detail) {
            val state = _uiState.value as? VideoPlaybackUiState.Success
            val bvid = desktopMetadataRelatedBvid
            if (state != null && state.info.bvid == bvid && state.info.cid == expected.request.cid) {
                val next = state.copy(related = detail.related, relatedLoadState = detail.relatedLoadState)
                _uiState.value = next
                if (detail.relatedLoadState == VideoPlaybackUiState.RelatedLoadState.READY)
                    updatePlaylist(next.info, detail.related, desktopPostPreload = { preload = it })
                desktopMetadataRelatedMirroredToken = token
            }
        }
    }
    if (preload.isNotEmpty()) {
        val source = com.bilipai.desktop.ui.DesktopOriginalVideoRelatedRequestSource(expected) {
            admission.ownsSubject() && currentLoadRequestToken == token &&
                metadataRelatedNativeSource(admission, token) === expected
        }
        try { preloadRelatedPlayUrls(preload, source) }
        catch (cancelled: CancellationException) { throw cancelled }
        catch (_: Exception) { Logger.w("PlayerVM", "Related preload capability unavailable") }
    }
}
private fun startDesktopMetadataRelated(
    scope: com.bilipai.desktop.ui.DesktopOriginalVideoMetadataReadScope,
    bvid: String, token: Long,
) {
    if (bvid.isBlank() || desktopMetadataRelatedToken == token) return
    lateinit var operation: Job
    operation = scope.launch(start = CoroutineStart.LAZY) { runDesktopMetadataRelated(scope, bvid, token, operation) }
    val linked = scope.presentation.admit {
        if (currentLoadRequestToken != token || desktopMetadataRelatedToken == token)
            throw CancellationException("Readonly related launch replaced")
        desktopMetadataRelatedToken = token
        desktopMetadataRelatedBvid = bvid
        desktopMetadataRelatedJob = operation
    }
    if (linked) operation.start() else operation.cancel()
}

/** Retry is a fresh real primary-metadata request, still owned by the
 * displayed entry/receipt. It does not restart playback or accept media. */
fun retryDesktopMetadataRelated(admission: com.bilipai.desktop.ui.DesktopOriginalVideoMetadataAdmission) {
    val token = desktopMetadataRelatedToken
    val bvid = desktopMetadataRelatedBvid
    if (_desktopMetadataAdmission.value !== admission || !admission.isCurrent() ||
        token != currentLoadRequestToken || bvid.isBlank() || desktopMetadataRelatedJob?.isActive == true ||
        _detailState.value.relatedLoadState != VideoPlaybackUiState.RelatedLoadState.FAILED) return
    lateinit var operation: Job
    operation = environment.invocations.launchMetadataRetry(admission, start = CoroutineStart.LAZY,
        onFailure = { failure ->
            val applied = admission.admit {
                if (_desktopMetadataAdmission.value === admission && token == currentLoadRequestToken &&
                    desktopMetadataRelatedJob === operation) {
                    _desktopMetadataRelatedFailure.value = failure
                    _detailState.update { if (it.requestToken == token)
                        it.copy(relatedLoadState = VideoPlaybackUiState.RelatedLoadState.FAILED) else it }
                    desktopMetadataRelatedJob = null
                }
            }
            if (applied) mirrorDesktopMetadataRelatedAfterNative(admission, token)
        }) { scope -> runDesktopMetadataRelated(scope, bvid, token, operation) }
    val linked = admission.admit {
        if (_desktopMetadataAdmission.value !== admission || token != currentLoadRequestToken ||
            (desktopMetadataRelatedJob?.let { !it.isCancelled && !it.isCompleted } == true))
            throw CancellationException("Readonly related retry replaced")
        desktopMetadataRelatedJob = operation
        desktopMetadataRelatedMirroredToken = Long.MIN_VALUE
        _desktopMetadataRelatedFailure.value = null
        _detailState.update { if (it.requestToken == token)
            it.copy(relatedLoadState = VideoPlaybackUiState.RelatedLoadState.LOADING) else it }
    }
    if (linked) {
        metadataRelatedNativeSource(admission, token)?.let { expected ->
            environment.admitNativePublication(expected) {
                if (metadataRelatedNativeSource(admission, token) === expected &&
                    _desktopMetadataAdmission.value === admission && currentLoadRequestToken == token)
                    _uiState.update { if (it is VideoPlaybackUiState.Success)
                        it.copy(relatedLoadState = VideoPlaybackUiState.RelatedLoadState.LOADING) else it }
            }
        }
        operation.start()
    } else operation.cancel()
}

